import itertools
from z3 import *

def solve_ramsey():
    n = 22
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((i, j))

    edge_vars = {}
    for i, j in edges:
        edge_vars[(i, j)] = Int(f'e_{i}_{j}')

    solver = Solver()

    # Edge constraints: 0 or 1
    for i, j in edges:
        solver.add(Or(edge_vars[(i, j)] == 0, edge_vars[(i, j)] == 1))

    # No red K4 (all 0)
    for clique in itertools.combinations(range(n), 4):
        solver.add(Or([edge_vars[tuple(sorted((clique[i], clique[j])))] != 0 
                       for i in range(4) for j in range(i + 1, 4)]))

    # No blue K5 (all 1)
    for clique in itertools.combinations(range(n), 5):
        solver.add(Or([edge_vars[tuple(sorted((clique[i], clique[j])))] != 1 
                       for i in range(5) for j in range(i + 1, 5)]))

    if solver.check() == sat:
        model = solver.model()
        result = []
        for i, j in edges:
            result.append(model.evaluate(edge_vars[(i, j)]).as_long())
        return result
    else:
        return None

