import random

def generate_random_coloring(n):
    num_edges = n * (n - 1) // 2
    return [random.randint(0, 1) for _ in range(num_edges)]

def count_monochromatic_cliques(n, coloring, red_clique_size, blue_clique_size):
    edges = {}
    idx = 0
    for i in range(n):
        for j in range(i + 1, n):
            edges[(i, j)] = coloring[idx]
            idx += 1

    red_count = 0
    for clique in itertools.combinations(range(n), red_clique_size):
        if all(edges[tuple(sorted((clique[i], clique[j])))] == 0 
               for i in range(red_clique_size) for j in range(i + 1, red_clique_size)):
            red_count += 1

    blue_count = 0
    for clique in itertools.combinations(range(n), blue_clique_size):
        if all(edges[tuple(sorted((clique[i], clique[j])))] == 1 
               for i in range(blue_clique_size) for j in range(i + 1, blue_clique_size)):
            blue_count += 1

    return red_count, blue_count

