def local_search(n, red_clique_size, blue_clique_size, max_iter=100000):
    num_edges = n * (n - 1) // 2
    coloring = [random.randint(0, 1) for _ in range(num_edges)]

    # Precompute edges for each clique
    edges_list = []
    for i in range(n):
        for j in range(i + 1, n):
            edges_list.append((i, j))

    edge_to_idx = {edge: i for i, edge in enumerate(edges_list)}

    red_cliques = [ [edge_to_idx[tuple(sorted((c[i], c[j])))] for i in range(red_clique_size) for j in range(i + 1, red_clique_size)] for c in itertools.combinations(range(n), red_clique_size)]
    blue_cliques = [ [edge_to_idx[tuple(sorted((c[i], c[j])))] for i in range(blue_clique_size) for j in range(i + 1, blue_clique_size)] for c in itertools.combinations(range(n), blue_clique_size)]

    def get_violations(current_coloring):
        red_v = [c for c in red_cliques if all(current_coloring[e] == 0 for e in c)]
        blue_v = [c for c in blue_cliques if all(current_coloring[e] == 1 for e in c)]
        return len(red_v) + len(blue_v)

    current_v = get_violations(coloring)

    for _ in range(max_iter):
        if current_v == 0:
            return coloring

        # Pick a random edge and flip it
        idx = random.randint(0, num_edges - 1)
        coloring[idx] = 1 - coloring[idx]
        new_v = get_violations(coloring)

        if new_v < current_v:
            current_v = new_v
        else:
            # Simulated annealing-like acceptance
            if random.random() < 0.01:
                current_v = new_v
            else:
                coloring[idx] = 1 - coloring[idx]
    return None

