import itertools

def check_construction():
    n = 25
    # Edges (i, j) are red if (j-i) mod 25 is in {1, 2, 4, 8, 16}
    # Otherwise blue.
    # Let's check if this has a red K4 or blue K5.

    def is_red(i, j):
        diff = abs(i - j)
        return (diff % 25) in [1, 2, 4, 8, 16]

    # Check for red K4
    for clique in itertools.combinations(range(n), 4):
        if all(is_red(clique[i], clique[j]) for i in range(4) for j in range(i + 1, 4)):
            return False, "Red K4 found"

    # Check for blue K5
    for clique in itertools.combinations(range(n), 5):
        if all(not is_red(clique[i], clique[j]) for i in range(5) for j in range(i + 1, 5)):
            return False, "Blue K5 found"

    return True, "No monochromatic K4 or K5"

